    images: [{ url: "https://images.unsplash.com/photo-1516245834210-c4c142787335?w=1080", alt: "Conceptual image of blockchain path leading to legislative building, symbolizing Trump's Crypto Clarity Act and market rebound", attribution: "Photo by Unsplash (via PulseTrends)", caption: "A conceptual pathway of digital assets leading towards legislative clarity, as President Trump champions a new era of crypto regulation.", category: "crypto" }],
